import numpy as np

def option_payoff(S, K, premium, option='call', position='long'):
    if option == 'call':
        payoff = np.maximum(S - K, 0)
    else:
        payoff = np.maximum(K - S, 0)

    if position == 'long':
        return payoff - premium
    else:
        return -payoff + premium

