from scipy.stats import norm
import numpy as np

def implied_vol(price, S, K, T, r, option='call'):
    def objective(sigma):
        d1 = (np.log(S/K) + (r+sigma**2/2)*T) / (sigma*np.sqrt(T))
        d2 = d1 - sigma*np.sqrt(T)
        if option == 'call':
            model = S*norm.cdf(d1) - K*np.exp(-r*T)*norm.cdf(d2)
        else:
            model = K*np.exp(-r*T)*norm.cdf(-d2) - S*norm.cdf(-d1)
        return model - price

    return brentq(objective, 0.01, 5.0)

